int functieStudent(struct Student* ht, int size, char* studName)
{
    char found = 0, i;
    for (i = 0; i < size && !found; i++)
    {
        if ((ht[i].name != 0) && (strcmp(ht[i].name, studName) == 0))
        {
            found = 1;
        }
    }

    if (found == 1)
        return i;
    else
        return -1;
}

