Care va fi rezultatul executiei urmatorului cod sursa?

#include <stdio.h>
int functie(int a, int b) {
    if (b == 0) return 0;
    if (b % 2 == 0) return functie(a + a, b / 2);
    return functie(a + a, b / 2) + a;
}
int main() {
    printf("%d", functie(4, 3));
    return 0;
}
